.action-button {
  padding: 10px 20px;
  background-color: #2563eb;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

/* Triggered when cursor enters button bounds */
.action-button:hover {
  background-color: #1d4ed8;
}

/* Accessible keyboard-navigation focus ring */
.action-button:focus-visible {
  outline: 3px solid #93c5fd;
  outline-offset: 2px;
}

/* Triggered during physical click/depression */
.action-button:active {
  transform: scale(0.98);
}

/* First table row gets prominent top border */
tbody tr:first-child {
  border-top: 3px solid #0f172a;
}

/* Last table row strips bottom border */
tbody tr:last-child {
  border-bottom: none;
}

/* Zebra striping alternating even rows */
tbody tr:nth-child(even) {
  background-color: #f8fafc;
}

/* Highlights every 3rd list item */
ul li:nth-child(3n) {
  font-weight: 700;
  color: #4f46e5;
}

/* 
 * Difference:
 * - Pseudo-class (:hover) targets an entire element in a specific state.
 * - Pseudo-element (::before) creates an abstract virtual element inside the target.
 */

.external-link {
  position: relative;
  color: #2563eb;
  text-decoration: none;
}

/* Appends an external link indicator arrow after the link text */
.external-link::after {
  content: " ";
  font-size: 0.85em;
  color: #64748b;
}

/* Inserts an animated status indicator dot before a username */
.user-online::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 8px;
  background-color: #10b981;
  border-radius: 50%;
}

/* Tooltip container */
.has-tooltip {
  position: relative;
  display: inline-block;
  cursor: help;
}

/* Hidden by default */
.has-tooltip::after {
  /* Reads text directly from custom data-tooltip HTML attribute */
  content: attr(data-tooltip);
  position: absolute;
  bottom: 125%;
  left: 50%;
  transform: translateX(-50%);

  padding: 6px 12px;
  background-color: #0f172a;
  color: #ffffff;
  font-size: 0.75rem;
  white-space: nowrap;
  border-radius: 4px;
  pointer-events: none;

  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

/* Revealed smoothly on hover */
.has-tooltip:hover::after {
  opacity: 1;
  transform: translateX(-50%) translateY(-4px);
}
